precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform DissolveFireUBO {
  vec4 fireColor1;
  vec4 fireColor2;
  vec4 fireColor3;
  vec2 spriteSize;
  float dirStrength;
  float dissolveSlide;
  float slideOffset;
  float slideOffsetSpeed;
  float fireAngle;
  float slideOffset2Speed;
  float dissolveDir;
  float ridgeStrength;
  float fireEdgeWidth;
  float fireIntensity;
  float distortStrength;
};
in vec4 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 v_color;
out vec2 v_uv;
out vec2 v_noiseUV;
out vec2 v_uvRatio;
out vec2 v_mainOffset;
out vec2 v_noiseOffset1;
out vec2 v_noiseOffset2;
out vec3 v_edgeParams;
vec4 vert () {
  vec4 pos = vec4(a_position);
  pos = cc_matViewProj * pos;
  v_uv = vec2(a_texCoord.x, 1.0 - a_texCoord.y);
  v_noiseUV = a_texCoord;
  v_color = a_color;
  float rad = radians(fireAngle);
  vec2 fireDir = vec2(cos(rad), sin(rad));
  float minSize = min(spriteSize.x, spriteSize.y);
  v_uvRatio = spriteSize / minSize;
  v_mainOffset = slideOffset * fireDir;
  v_noiseOffset1 = v_mainOffset * slideOffsetSpeed;
  v_noiseOffset2 = v_mainOffset * slideOffset2Speed;
  float edgeWidth = 0.1;
  v_edgeParams.x = dissolveSlide * (1.0 + edgeWidth) - edgeWidth;
  v_edgeParams.y = v_edgeParams.x + edgeWidth;
  v_edgeParams.z = v_edgeParams.x;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
uniform sampler2D cc_spriteTexture;
layout(std140) uniform DissolveFireUBO {
  vec4 fireColor1;
  vec4 fireColor2;
  vec4 fireColor3;
  vec2 spriteSize;
  float dirStrength;
  float dissolveSlide;
  float slideOffset;
  float slideOffsetSpeed;
  float fireAngle;
  float slideOffset2Speed;
  float dissolveDir;
  float ridgeStrength;
  float fireEdgeWidth;
  float fireIntensity;
  float distortStrength;
};
in vec2 v_uv;
in vec2 v_noiseUV;
in vec4 v_color;
in vec2 v_uvRatio;
in vec2 v_mainOffset;
in vec2 v_noiseOffset1;
in vec2 v_noiseOffset2;
in vec3 v_edgeParams;
uniform sampler2D u_dissolveMap;
uniform sampler2D fireNoiseMap;
uniform sampler2D fireNoiseMap2;
vec2 getWarpDistortion (vec2 noiseUV) {
  vec2 uv = fract(noiseUV + v_mainOffset);
  vec2 noise = texture(fireNoiseMap, uv).rg;
  noise = noise * 2.0 - 1.0;
  return noise * distortStrength * step(0.001, dissolveSlide);
}
float getDissolveDir(vec2 noiseUV) {
  float d   = floor(dissolveDir + 0.5);
  float gx  = noiseUV.x;
  float gy  = noiseUV.y;
  float igx = 1.0 - gx;
  float igy = 1.0 - gy;
  if (d < 0.5) return gx;
  if (d < 1.5) return igx;
  if (d < 2.5) return igy;
  if (d < 3.5) return gy;
  if (d < 4.5) return (gx  + igy) * 0.5;
  if (d < 5.5) return (igx + igy) * 0.5;
  if (d < 6.5) return (gx  + gy ) * 0.5;
  return             (igx + gy ) * 0.5;
}
float blendNoiseLayers(float dp1, float dp2) {
  float screen = 1.0 - (1.0 - dp1) * (1.0 - dp2);
  float ridge  = pow(1.0 - abs(dp1 - dp2), 2.0);
  return screen * mix(1.0, ridge, ridgeStrength);
}
float computeFireNoise(vec2 noiseUV) {
  vec2 baseUV   = noiseUV * v_uvRatio;
  float dp1     = texture(fireNoiseMap,  fract(baseUV + v_noiseOffset1)).r;
  float dp2     = texture(fireNoiseMap2, fract(baseUV + v_noiseOffset2)).r;
  return blendNoiseLayers(dp1, dp2);
}
vec4 frag() {
  vec2 distortion = getWarpDistortion(v_noiseUV);
  vec2 distortUV      = v_uv + vec2(distortion.x, -distortion.y);
  vec2 distortNoiseUV = v_noiseUV + distortion;
    vec2 tileUV = distortNoiseUV * v_uvRatio;
    float dissolveValue = texture(u_dissolveMap, fract(tileUV)).r;
    float dissolveDirValue = getDissolveDir(v_noiseUV);
    float dissolveMix = mix(dissolveValue, pow(dissolveDirValue, 1.2), dirStrength);
    float alpha = smoothstep(v_edgeParams.x, v_edgeParams.y, dissolveMix);
  float currentEdge = v_edgeParams.z;
  float distortRange = smoothstep(currentEdge - fireEdgeWidth, currentEdge, dissolveMix) - smoothstep(currentEdge, currentEdge + fireEdgeWidth, dissolveMix);
  distortRange = clamp(distortRange, 0.0, 1.0);
  vec2 finalSpriteUV = mix(v_uv, distortUV, distortRange);
  vec4 distortCol = texture(cc_spriteTexture, finalSpriteUV);
  vec4  spriteCol      = distortCol * v_color;
  float spriteA       = spriteCol.a * alpha;
  vec3  premultipliedRGB    = spriteCol.rgb * spriteA;
  float coverageAlpha = spriteA;
  float progressGate = smoothstep(0.0, 0.01, dissolveSlide) * smoothstep(1.0, 0.99, dissolveSlide);
  float fireMask     = distortRange * progressGate;
  float dp = computeFireNoise(distortNoiseUV);
  float c_mask = clamp(dp, 0.0, 1.0);
  float t_outer_mid  = smoothstep(0.1, 0.5, c_mask);
  float fireColorBlur = 0.23;
  float fireColorMinifyLevel = 1.0;
  float blurredLevel = clamp(fireColorMinifyLevel - fireColorBlur * fireColorMinifyLevel, 0.0, 2.0);
  float t_mid_inner  = smoothstep(blurredLevel, fireColorMinifyLevel, c_mask);
  vec3 fireCol = mix(fireColor1.rgb, fireColor2.rgb, t_outer_mid);
  fireCol      = mix(fireCol,        fireColor3.rgb, t_mid_inner);
  float fireFinalAlpha = (c_mask) * fireMask * fireIntensity;
  premultipliedRGB += fireCol * fireFinalAlpha;
  return vec4(premultipliedRGB, clamp(coverageAlpha, 0.0, 1.0));
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

