glsl3.frag:
precision highp float;
uniform sampler2D cc_spriteTexture;
uniform sampler2D wrapTexture;
layout(std140) uniform Constants {
  float warpStrength;
  float timeLine;
};
in vec2 v_uv;
vec4 warpFrag () {
  vec2 uv = v_uv;
  vec2 noiseUV =  fract(vec2(0.0, timeLine) + uv);
  vec4 origCol = texture(cc_spriteTexture, uv);
  vec2 noise = texture(wrapTexture, noiseUV).rg;
  noise = noise * 2.0 - 1.0;
  uv += (noise) * warpStrength;
  vec4 col = texture(cc_spriteTexture, uv);
  vec3 premultipliedRGB = col.rgb * col.a;
  vec3 finalCol = ( premultipliedRGB * 1.1)  + origCol.rgb * 0.3;
  return col;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = warpFrag(); }

